```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "petualangan-sang-pemakan", title: "Petualangan Sang Pemakan", seed: "pemakan-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Ilmu Pengetahuan Alam",
    concept: "Penggolongan hewan berdasarkan jenis makanannya: herbivora, karnivora, omnivora",
    objectives: ["Mengelompokkan hewan berdasarkan jenis makanannya dengan tepat"],
    misconceptions: ["Ayam dianggap herbivora karena sering terlihat memakan biji-bijian, padahal juga memakan serangga dan cacing sehingga termasuk omnivora"],
    mode: "category",
    categories: [
      { id: "herbivora", label: "Herbivora", color: "#3FA34D" },
      { id: "karnivora", label: "Karnivora", color: "#E5484D" },
      { id: "omnivora",  label: "Omnivora",  color: "#F2A93B" }
    ],
    items: [
      { id: "sapi",    label: "Sapi",    category: "herbivora", explain: "Memakan rumput dan tumbuhan hijau, jadi herbivora." },
      { id: "kambing", label: "Kambing", category: "herbivora", explain: "Memakan daun dan rumput, jadi herbivora." },
      { id: "kelinci", label: "Kelinci", category: "herbivora", explain: "Memakan sayuran dan tumbuhan, jadi herbivora." },
      { id: "harimau", label: "Harimau", category: "karnivora", explain: "Memakan daging hasil berburu, jadi karnivora." },
      { id: "singa",   label: "Singa",   category: "karnivora", explain: "Pemangsa daging di sabana, jadi karnivora." },
      { id: "elang",   label: "Elang",   category: "karnivora", explain: "Pemangsa daging dengan cakar tajam, jadi karnivora." },
      { id: "ayam",    label: "Ayam",    category: "omnivora",  explain: "Memakan biji-bijian sekaligus serangga dan cacing, jadi omnivora." },
      { id: "babi",    label: "Babi",    category: "omnivora",  explain: "Memakan tumbuhan dan hewan kecil, jadi omnivora." },
      { id: "beruang", label: "Beruang", category: "omnivora",  explain: "Memakan buah, madu, dan ikan, jadi omnivora." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 5, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 300, maxSpeed: 600, accel: 4 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",  w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 20, speed: 20 }
  }
});
// END_OF_MANIFEST
```

Game "Petualangan Sang Pemakan" adalah Endless Runner edukasi bertema Cartoon di mana pemain mengumpulkan hewan sesuai target (Herbivora, Karnivora, Omnivora). Mode Santai dipakai dengan 5 nyawa dan tempo lambat sesuai pilihan Anda.
